-- Additive feed metadata; no recipe rewrites or changes to access boundaries.
create or replace function public.recipe_feed(page_offset integer default 0, page_size integer default 24, search_text text default '', tag text default '') returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',content->>'title','summary',content->>'summary','minutes',(content->>'minutes')::int,'servings',content->'servings','difficulty',content->'difficulty','tags',tags,'ingredients',content->'ingredients','image',case when j.state='ready' and j.bucket='recipe-catalog' then coalesce(j.thumbnail_path,j.asset_path) else null end) order by r.created_at,r.id),'[]') from (select * from public.recipe_documents where published and (search_text='' or content->>'title' ilike '%'||left(search_text,100)||'%') and (tag='' or tag=any(tags)) order by created_at,id limit least(greatest(page_size,1),48) offset greatest(page_offset,0)) r left join public.recipe_asset_jobs j on j.recipe_id=r.id and j.step=-1;
$$;
